(function (global) {
  'use strict';

  // Base64 encoded WebAssembly binary for libav.js (offline / file:// execution)
  const b64 = "";

  function decodeBase64(str) {
    const bin = atob(str);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    return bytes.buffer;
  }

  let _cachedBinary = null;
  let _compiledModule = null;

  global.getLibavWasmBinary = function () {
    if (!_cachedBinary) {
      _cachedBinary = decodeBase64(b64);
    }
    return _cachedBinary;
  };

  global.instantiateLibavWasm = async function (imports, successCallback) {
    try {
      const binary = global.getLibavWasmBinary();
      if (!_compiledModule) {
        _compiledModule = await WebAssembly.compile(binary);
      }
      const instance = await WebAssembly.instantiate(_compiledModule, imports);
      successCallback(instance);
      return instance;
    } catch (err) {
      console.error('[libav-wasm-data] instantiate error:', err);
      throw err;
    }
  };
})(typeof window !== 'undefined' ? window : (typeof self !== 'undefined' ? self : globalThis));
